  "inlineSchema": "// =============================================================================\n// Moneflow — Prisma schema (PostgreSQL)\n//\n// Single source of truth for the database. Balances live ONLY in PostgreSQL:\n// no fake balance values are ever computed in the frontend.\n// =============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// =============================================================================\n// Enums\n// =============================================================================\n\nenum TransactionType {\n  TRANSFER // direct send-money between two users\n  REQUEST_SETTLEMENT // settlement of an approved money request\n}\n\nenum TransactionStatus {\n  PENDING\n  SUCCEEDED\n  FAILED\n}\n\nenum RequestStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  CANCELLED\n}\n\n// =============================================================================\n// User\n// =============================================================================\n\nmodel User {\n  id        String   @id @default(uuid())\n  name      String\n  email     String   @unique\n  phone     String?  @unique\n  password  String // bcrypt hash — plaintext passwords are NEVER stored\n  active    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // One user has exactly one account (one-to-one, enforced by Account.userId @unique).\n  account Account?\n\n  // Money requests where this user is the requester (wants to RECEIVE money)\n  // or the requested-from user (asked to PAY).\n  sentRequests     MoneyRequest[] @relation(\"RequesterRequests\")\n  receivedRequests MoneyRequest[] @relation(\"RequestedFromRequests\")\n\n  // NOTE: transaction history is reachable through the user's Account\n  // (Account.sentTransactions / Account.receivedTransactions), because every\n  // Transaction references sender/receiver *accounts* — this is what keeps the\n  // audit trail immutable even if a user profile changes.\n  @@index([name])\n}\n\n// =============================================================================\n// Account\n// =============================================================================\n\nmodel Account {\n  id        String   @id @default(uuid())\n  userId    String   @unique // one-to-one: exactly one account per user\n  balance   Decimal  @default(0) @db.Decimal(18, 2) // BDT, 2 decimal places (poisha)\n  currency  String   @default(\"BDT\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Restrict)\n\n  sentTransactions     Transaction[] @relation(\"SenderAccountTransactions\")\n  receivedTransactions Transaction[] @relation(\"ReceiverAccountTransactions\")\n\n  // NOTE: the BDT 100,000 welcome credit is applied by an explicit database\n  // operation inside the same DB transaction that creates the user + account\n  // (registration service / seed script). It is NOT baked into the schema\n  // default, so every balance change is explicit and auditable.\n}\n\n// =============================================================================\n// Transaction  — append-only money-movement ledger\n// =============================================================================\n\nmodel Transaction {\n  id     String            @id @default(uuid())\n  type   TransactionType\n  status TransactionStatus @default(PENDING)\n\n  senderAccountId   String\n  receiverAccountId String\n  amount            Decimal @db.Decimal(18, 2) // always positive\n  currency          String  @default(\"BDT\")\n\n  // ---- Audit snapshot (set once at creation, immutable) ----\n  senderNameAtTime     String\n  receiverNameAtTime   String\n  senderBalanceAfter   Decimal @db.Decimal(18, 2)\n  receiverBalanceAfter Decimal @db.Decimal(18, 2)\n\n  idempotencyKey String\n  description    String?\n\n  // Populated when this transaction settles an approved money request.\n  moneyRequestId String?\n  moneyRequest   MoneyRequest? @relation(fields: [moneyRequestId], references: [id], onDelete: Restrict)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  senderAccount   Account @relation(\"SenderAccountTransactions\", fields: [senderAccountId], references: [id], onDelete: Restrict)\n  receiverAccount Account @relation(\"ReceiverAccountTransactions\", fields: [receiverAccountId], references: [id], onDelete: Restrict)\n\n  // Idempotency: one key per sender per operation — replayed requests get the\n  // same transaction and can never double-spend.\n  @@unique([senderAccountId, idempotencyKey])\n  // History lookups (\"all my transactions\", newest-first).\n  @@index([senderAccountId, createdAt])\n  @@index([receiverAccountId, createdAt])\n  // Status filters and request-settlement lookups.\n  @@index([status])\n  @@index([moneyRequestId])\n}\n\n// =============================================================================\n// MoneyRequest  — \"please pay me\" / \"please pay X\"\n// =============================================================================\n\nmodel MoneyRequest {\n  id              String        @id @default(uuid())\n  requesterId     String // user who wants to *receive* money\n  requestedFromId String // user who is being asked to *pay*\n  amount          Decimal       @db.Decimal(18, 2) // always positive\n  currency        String        @default(\"BDT\")\n  description     String?\n  status          RequestStatus @default(PENDING)\n\n  idempotencyKey String\n\n  respondedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  requester     User          @relation(\"RequesterRequests\", fields: [requesterId], references: [id], onDelete: Restrict)\n  requestedFrom User          @relation(\"RequestedFromRequests\", fields: [requestedFromId], references: [id], onDelete: Restrict)\n  settlements   Transaction[] // APPROVED request -> settlement transaction(s)\n\n  // Idempotency: one key per requester per operation.\n  @@unique([requesterId, idempotencyKey])\n  // \"Pending requests for me\" is the hot read:\n  // WHERE requestedFromId=? AND status='PENDING' ORDER BY createdAt DESC.\n  @@index([requestedFromId, status, createdAt])\n  // \"My sent requests\".\n  @@index([requesterId, createdAt])\n}\n",
